mapper.select:
SELECT id, title, description, creator_id, assignee_id, status
FROM tickets
WHERE id = #{id}

mapper.update:
UPDATE tickets
SET status = 'CANCELLED'
WHERE id = #{id}
  AND creator_id = #{actorId}
  AND status = 'OPEN'

UPDATE tickets
SET status = 'IN_PROGRESS', assignee_id = #{actorId}
WHERE id = #{id}
  AND status = 'OPEN'
  AND assignee_id IS NULL

UPDATE tickets
SET status = 'RESOLVED'
WHERE id = #{id}
  AND assignee_id = #{actorId}
  AND status = 'IN_PROGRESS'
